p &= \sqrt {2x^2 - 4x\sin^2 \alpha }  + 2x \\
x &\le \sqrt {2x^2 - 4x\sin^2 \alpha }  \le 2x - 2x\sin^2 \alpha  + \frac{1}{{x^2 }}\\
1 &\le x\sin^2 \alpha  \le 
\left\lfloor {\frac{{3x^2 }}{{4x - 2}}} \right\rfloor  \le \frac{{3x^2 }}{4} < \frac{{54x}}{4} \\
3x^2 &< 2024x\\
x &< \frac{{20145}}{{31}}
\end{align*}

